def is_Sub_Array(A, B, n, m):
    # Check if the length of A is less than the length of B
    if len(A) < len(B):
        return False

    # Iterate through each element of A
    for i in range(n):
        # Check if the current element of A matches the first element of B
        if A[i] == B[0]:
            # Check if the remaining elements of A match the remaining elements of B
            for j in range(1, m):
                if A[i + j] != B[j]:
                    return False
            return True

    return False
```

