def jacobsthal_lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        # Initialize the first two numbers of the sequence
        a, b = 2, 1
        # Calculate the nth jacobsthal-lucas number iteratively
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b
